create schema auth;create schema private;create schema storage;
create role anon;create role authenticated;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('test.actor',true),'')::uuid$$;
create function private.effective_user_id() returns uuid language sql stable as $$select auth.uid()$$;
create table roles(id uuid primary key,key text);
create table profiles(id uuid primary key,role_id uuid references roles,status text default 'active');
create function private.current_role_key() returns text language sql stable security definer set search_path='' as $$select r.key from public.profiles p join public.roles r on r.id=p.role_id where p.id=auth.uid() and p.status='active'$$;
create table public.test_grants(module text,action text,allowed boolean default true,primary key(module,action));
create function private.has_module_access(m text,a text,p text default 'web') returns boolean language sql stable security definer set search_path='' as $$select private.current_role_key() is not null and coalesce((select allowed from public.test_grants where module=m and action=a),true)$$;
create table crm_records(collection text,id text,data jsonb,primary key(collection,id));
create table storage.objects(bucket_id text,name text,archived_at timestamptz,is_delete_marker boolean default false);
create table privileged_security_events(event_type text,real_actor_user_id uuid,effective_actor_user_id uuid,target_type text,target_id text,reason text,metadata jsonb);
create table job_order_items(id uuid primary key,job_order_id uuid,quantity numeric,quantity_issued numeric default 0,quantity_used numeric default 0,quantity_matched numeric default 0,requires_inventory boolean default true);
create table inventory_balances(id uuid primary key,quantity_reserved numeric,quantity_on_hand numeric,variant_id uuid,version bigint default 0,updated_at timestamptz);
create table stock_reservations(id uuid primary key,job_order_item_id uuid,inventory_balance_id uuid,quantity numeric,quantity_released numeric default 0,status text default 'active',consumed_at timestamptz,released_at timestamptz,updated_at timestamptz);
create table pick_list_items(id uuid primary key,reservation_id uuid,quantity_required numeric,quantity_picked numeric,updated_at timestamptz);
create table product_variants(id uuid primary key,active boolean default true);
insert into roles values('00000000-0000-4000-8000-000000000001','admin'),('00000000-0000-4000-8000-000000000002','installer');
insert into profiles values('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','active'),('10000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000002','active');
insert into product_variants values('30000000-0000-4000-8000-000000000001',true);
grant usage on schema public,private,auth to authenticated;
grant execute on all functions in schema private,auth to authenticated;
grant select,insert,update,delete on crm_records to authenticated;

create function private.access_decision(u uuid,m text,a text,p text) returns jsonb language sql stable as $$select jsonb_build_object('allowed',exists(select 1 from public.profiles where id=u and status='active'))$$;
create table quotations(id uuid primary key,lead_id uuid,contact_id uuid,status text,accepted_at timestamptz);
create table leads(id uuid primary key,stage text,won_at timestamptz);
create table products(id uuid primary key,track_inventory boolean);
create table quotation_items(id uuid default gen_random_uuid(),quotation_id uuid,product_id uuid,variant_id uuid,sku_snapshot text,description text,quantity numeric,unit_price numeric,tax_rate numeric);
create table quotation_status_history(quotation_id uuid,from_status text,to_status text,changed_by uuid);
create table job_orders(id uuid primary key default gen_random_uuid(),job_number bigint generated always as identity,quotation_id uuid,lead_id uuid,contact_id uuid,status text,created_by uuid,workflow_stage text default 'Confirmed');
create table tasks(id uuid primary key default gen_random_uuid(),title text,description text,task_type text,job_order_id uuid,status text,priority text,created_by uuid,job_stage text,workflow_action text);
create table warehouses(id uuid primary key default gen_random_uuid(),active boolean default true,created_at timestamptz default now());
create table pick_lists(id uuid primary key default gen_random_uuid(),job_order_id uuid,warehouse_id uuid,created_by uuid);
alter table job_order_items alter column id set default gen_random_uuid();
alter table job_order_items add column quotation_item_id uuid,add column product_id uuid,add column variant_id uuid,add column sku_snapshot text,add column description text,add column unit_price_snapshot numeric,add column tax_rate_snapshot numeric,add column line_kind text;
alter table stock_reservations alter column id set default gen_random_uuid();
alter table stock_reservations add column job_order_id uuid,add column variant_id uuid,add column warehouse_id uuid;
alter table pick_list_items alter column id set default gen_random_uuid();
alter table pick_list_items add column pick_list_id uuid,add column variant_id uuid;
grant select,insert,update on all tables in schema public to authenticated;
grant usage on all sequences in schema public to authenticated;
